/**
 * Offline species lookup and search over the bundled `speciesIndex.json`
 * (generated by `scripts/build-local-data.mjs` — every species of Gens 1-9
 * plus its huntable alternate varieties).
 *
 * Everything here is synchronous and network-free: search keys are normalised
 * once at module load, so a query is a single pass over ~1,100 entries.
 */
import speciesIndex from '@renderer/data/speciesIndex.json';
import type { TargetRef } from '@shared/types';
import { targetSprites } from './sprites';

// ───────────────────────────── Index decoding ─────────────────────────────

/** Row shapes of `speciesIndex.json` (short keys keep the bundle small). */
interface RawForm {
  /** PokeAPI `pokemon` id. */
  i: number;
  /** `pokemon` slug. */
  s: string;
  /** Display name. */
  n: string;
  /** Short form label. */
  l: string;
  /** Type slugs in slot order. */
  t: string[];
}

interface RawSpecies {
  i: number;
  /** `pokemon-species` slug. */
  s: string;
  n: string;
  /** Generation the species was introduced in. */
  g: number;
  t: string[];
  /** Slug of the default variety when it differs from `s` (`deoxys-normal`). */
  d?: string;
  /** Form label of the default variety, present only alongside `f`. */
  l?: string;
  f?: RawForm[];
}

/** A huntable alternate variety of a species — a regional form, gender variety, forme, … */
export interface FormEntry {
  /** PokeAPI `pokemon` id (10001+); addresses sprites and `/pokemon/{id}`. */
  pokemonId: number;
  /** National Pokédex number of the species this variety belongs to. */
  speciesId: number;
  /** PokeAPI `pokemon` slug, e.g. `vulpix-alola`. */
  slug: string;
  /** Full display name, e.g. `Alolan Vulpix`. */
  name: string;
  /** Short label for a form picker, e.g. `Alolan Form`. */
  label: string;
  /** PokeAPI type slugs in slot order. */
  types: string[];
}

export interface SpeciesEntry {
  /** National Pokédex number; also the `pokemon` id of the base variety. */
  id: number;
  /** PokeAPI `pokemon-species` slug, e.g. `deoxys`. */
  slug: string;
  /** PokeAPI `pokemon` slug of the base variety, e.g. `deoxys-normal` (usually equal to `slug`). */
  pokemonSlug: string;
  /** English display name, e.g. `Mr. Mime`, `Farfetch'd`, `Nidoran♀`. */
  name: string;
  /** Generation the species debuted in (1–9). */
  gen: number;
  /** Types of the base variety, in slot order. */
  types: string[];
  /** Label of the base variety when the species has `forms` (`Normal Forme`, `Male`); null otherwise. */
  baseLabel: string | null;
  /** Huntable alternate varieties; empty for most species. */
  forms: FormEntry[];
}

/** The 18 regular types in the games' canonical order. */
export const POKEMON_TYPES: readonly string[] = [
  'normal',
  'fire',
  'water',
  'electric',
  'grass',
  'ice',
  'fighting',
  'poison',
  'ground',
  'flying',
  'psychic',
  'bug',
  'rock',
  'ghost',
  'dragon',
  'dark',
  'steel',
  'fairy',
];

const rawSpecies: readonly RawSpecies[] = speciesIndex.species;

function decodeSpecies(raw: RawSpecies): SpeciesEntry {
  return {
    id: raw.i,
    slug: raw.s,
    pokemonSlug: raw.d ?? raw.s,
    name: raw.n,
    gen: raw.g,
    types: raw.t,
    baseLabel: raw.l ?? null,
    forms: (raw.f ?? []).map((form) => ({
      pokemonId: form.i,
      speciesId: raw.i,
      slug: form.s,
      name: form.n,
      label: form.l,
      types: form.t,
    })),
  };
}

/** Every species in National Dex order. Treat as read-only. */
export const ALL_SPECIES: readonly SpeciesEntry[] = rawSpecies.map(decodeSpecies);

/** Generations covered by the bundled index, ascending. */
export const GENERATIONS: readonly number[] = [
  ...new Set(ALL_SPECIES.map((entry) => entry.gen)),
].sort((a, b) => a - b);

/** A species together with the specific variety referred to (null = base variety). */
export interface VarietyRef {
  species: SpeciesEntry;
  form: FormEntry | null;
}

const speciesById = new Map<number, SpeciesEntry>();
const varietyByPokemonId = new Map<number, VarietyRef>();
const varietyBySlug = new Map<string, VarietyRef>();

for (const species of ALL_SPECIES) {
  speciesById.set(species.id, species);
  const base: VarietyRef = { species, form: null };
  varietyByPokemonId.set(species.id, base);
  varietyBySlug.set(species.slug, base);
  varietyBySlug.set(species.pokemonSlug, base);
  for (const form of species.forms) {
    const ref: VarietyRef = { species, form };
    varietyByPokemonId.set(form.pokemonId, ref);
    varietyBySlug.set(form.slug, ref);
  }
}

/** Species by National Dex number. */
export function getSpecies(id: number): SpeciesEntry | null {
  return speciesById.get(id) ?? null;
}

/** An alternate variety by its PokeAPI `pokemon` id; null for base varieties and unknown ids. */
export function getForm(pokemonId: number): FormEntry | null {
  return varietyByPokemonId.get(pokemonId)?.form ?? null;
}

/** Resolves any PokeAPI `pokemon` id — base variety or alternate form — to its index entries. */
export function findByPokemonId(pokemonId: number): VarietyRef | null {
  return varietyByPokemonId.get(pokemonId) ?? null;
}

/** Resolves a `pokemon-species` slug or a `pokemon` slug (`deoxys`, `deoxys-normal`, `vulpix-alola`). */
export function findBySlug(slug: string): VarietyRef | null {
  return varietyBySlug.get(slug.trim().toLowerCase()) ?? null;
}

/** Display name for a `pokemon` id, e.g. `10103` → `Alolan Vulpix`; null when not in the index. */
export function displayName(pokemonId: number): string | null {
  const ref = varietyByPokemonId.get(pokemonId);
  return ref ? (ref.form?.name ?? ref.species.name) : null;
}

/** Builds the snapshot stored on a hunt for a species, or for one of its alternate varieties. */
export function toTargetRef(entry: SpeciesEntry, form?: FormEntry | null): TargetRef {
  if (form && form.speciesId !== entry.id) {
    throw new Error(`Form "${form.slug}" does not belong to species "${entry.slug}"`);
  }
  const pokemonId = form?.pokemonId ?? entry.id;
  return {
    speciesId: entry.id,
    pokemonId,
    slug: form?.slug ?? entry.pokemonSlug,
    name: form?.name ?? entry.name,
    types: [...(form?.types ?? entry.types)],
    ...targetSprites(pokemonId),
  };
}

// ───────────────────────────── Search ─────────────────────────────

/**
 * Canonical form used on both sides of a comparison: lower-case, diacritics
 * stripped, joining punctuation removed (`Farfetch'd` → `farfetchd`,
 * `Mr. Mime` → `mr mime`, `Type: Null` → `type null`), every other
 * non-alphanumeric run collapsed to one space (`Ho-Oh` → `ho oh`). Compatibility
 * characters are folded first, so full-width input from an IME (`ｐｉｋａ`) works.
 */
export function normalizeSearchText(input: string): string {
  return input
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/♀/g, ' f ')
    .replace(/♂/g, ' m ')
    .replace(/['\u2018\u2019.:]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

interface SearchKey {
  /** Normalised text with single spaces. */
  text: string;
  /** `text` without spaces — lets `mrmime`, `hooh`, `porygonz` match. */
  compact: string;
  words: string[];
}

interface SearchItem extends VarietyRef {
  pokemonId: number;
  name: string;
  types: string[];
  /** Display name first, then aliases (slug spelling, spelled-out gender). */
  keys: SearchKey[];
}

function toKey(text: string): SearchKey {
  return { text, compact: text.replaceAll(' ', ''), words: text.split(' ') };
}

function buildKeys(name: string, slug: string, extraSlug?: string): SearchKey[] {
  const texts = new Set<string>([normalizeSearchText(name)]);
  // The slug spelling makes "vulpix alola" / "tauros paldea blaze" hit their forms.
  texts.add(normalizeSearchText(slug));
  if (extraSlug) texts.add(normalizeSearchText(extraSlug));
  if (name.includes('♀')) texts.add(normalizeSearchText(name.replace('♀', ' female')));
  if (name.includes('♂')) texts.add(normalizeSearchText(name.replace('♂', ' male')));
  texts.delete('');
  return [...texts].map(toKey);
}

/** Flat list in result order: each species followed by its forms. */
const SEARCH_ITEMS: readonly SearchItem[] = ALL_SPECIES.flatMap((species) => [
  {
    species,
    form: null,
    pokemonId: species.id,
    name: species.name,
    types: species.types,
    keys: buildKeys(species.name, species.slug, species.pokemonSlug),
  },
  ...species.forms.map((form) => ({
    species,
    form,
    pokemonId: form.pokemonId,
    name: form.name,
    types: form.types,
    keys: buildKeys(form.name, form.slug),
  })),
]);

/**
 * How a result matched, best first:
 * `dex` (number typed) › `exact` › `prefix` › `word` (a later word starts with
 * the query, or every query word starts a different word) › `substring` ›
 * `fuzzy` (small typo). `all` marks the unranked listing of an empty query.
 */
export type SearchMatchKind = 'dex' | 'exact' | 'prefix' | 'word' | 'substring' | 'fuzzy' | 'all';

export interface SpeciesSearchOptions {
  /** Maximum number of results (default 12). */
  limit?: number;
  /** Only species introduced in this generation; alternate forms follow their species. */
  generation?: number | null;
  /** Only varieties that have this type (PokeAPI slug); forms are matched on their own typing. */
  type?: string | null;
  /** Set false to search base species only (default true). */
  includeForms?: boolean;
}

export interface SpeciesSearchResult extends VarietyRef {
  /** PokeAPI `pokemon` id of the hit (`form.pokemonId` or `species.id`). */
  pokemonId: number;
  /** Display name of the hit. */
  name: string;
  /** Types of the hit. */
  types: string[];
  match: SearchMatchKind;
  /** Higher is better; only comparable within one result list. */
  score: number;
}

export const DEFAULT_SEARCH_LIMIT = 12;

const SCORE = {
  dexExact: 1000,
  exact: 900,
  prefix: 800,
  dexPrefix: 750,
  word: 700,
  substring: 600,
  fuzzy: 500,
} as const;

/** Shorter queries are too ambiguous to guess a typo in. */
const MIN_FUZZY_LENGTH = 4;

function matchKindFor(score: number): SearchMatchKind {
  if (score >= SCORE.dexExact || score === SCORE.dexPrefix) return 'dex';
  if (score >= SCORE.exact) return 'exact';
  if (score >= SCORE.prefix) return 'prefix';
  if (score >= SCORE.word) return 'word';
  if (score >= SCORE.substring) return 'substring';
  return 'fuzzy';
}

/** True when every token is a prefix of a different word (order-independent). */
function tokensStartWords(tokens: readonly string[], words: readonly string[], used = 0): boolean {
  const [token, ...rest] = tokens;
  if (token === undefined) return true;
  for (let index = 0; index < words.length; index += 1) {
    const bit = 1 << index;
    if ((used & bit) === 0 && words[index]?.startsWith(token)) {
      if (tokensStartWords(rest, words, used | bit)) return true;
    }
  }
  return false;
}

function scoreKey(key: SearchKey, query: SearchKey): number {
  if (key.text === query.text || key.compact === query.compact) return SCORE.exact;
  if (key.text.startsWith(query.text) || key.compact.startsWith(query.compact)) return SCORE.prefix;
  if (query.words.length <= key.words.length && tokensStartWords(query.words, key.words)) {
    return SCORE.word;
  }
  // Substrings must sit inside one word (or span words exactly as typed): matching
  // across the compacted name would find "mega" in "Mr. Mime Galar".
  if (key.words.some((word) => word.includes(query.compact)) || key.text.includes(query.text)) {
    return SCORE.substring;
  }
  return 0;
}

const MAX_FUZZY_LENGTH = 48;
// Rolling rows for the edit-distance DP, reused across calls to avoid per-query garbage.
const DISTANCE_ROWS = [
  new Int16Array(MAX_FUZZY_LENGTH + 1),
  new Int16Array(MAX_FUZZY_LENGTH + 1),
  new Int16Array(MAX_FUZZY_LENGTH + 1),
] as const;

/**
 * Damerau–Levenshtein distance (adjacent transpositions count as one edit),
 * abandoning early once it must exceed `max`; returns `max + 1` in that case.
 */
function editDistance(a: string, b: string, max: number): number {
  const lengthA = a.length;
  const lengthB = b.length;
  if (Math.abs(lengthA - lengthB) > max) return max + 1;
  if (lengthA > MAX_FUZZY_LENGTH || lengthB > MAX_FUZZY_LENGTH) return max + 1;

  let [beforePrevious, previous, current] = DISTANCE_ROWS;
  for (let j = 0; j <= lengthB; j += 1) previous[j] = j;

  for (let i = 1; i <= lengthA; i += 1) {
    current[0] = i;
    let rowMin = i;
    const charA = a.charCodeAt(i - 1);
    for (let j = 1; j <= lengthB; j += 1) {
      const charB = b.charCodeAt(j - 1);
      let value = Math.min(
        (previous[j] ?? 0) + 1,
        (current[j - 1] ?? 0) + 1,
        (previous[j - 1] ?? 0) + (charA === charB ? 0 : 1),
      );
      if (i > 1 && j > 1 && charA === b.charCodeAt(j - 2) && a.charCodeAt(i - 2) === charB) {
        value = Math.min(value, (beforePrevious[j - 2] ?? 0) + 1);
      }
      current[j] = value;
      if (value < rowMin) rowMin = value;
    }
    if (rowMin > max) return max + 1;
    const recycled = beforePrevious;
    beforePrevious = previous;
    previous = current;
    current = recycled;
  }
  return previous[lengthB] ?? max + 1;
}

/** Typos tolerated in a string of the given (compact) length: one edit, two for long names. */
function typoBudget(length: number): number {
  if (length < MIN_FUZZY_LENGTH) return 0;
  return length <= 6 ? 1 : 2;
}

/**
 * Typo-tolerant score: the query is compared with the whole name and — so
 * results survive while the user is still typing — with the name's prefix of
 * the same length. 0 when the name is not within the typo budget.
 */
function fuzzyScore(key: SearchKey, query: SearchKey): number {
  const queryLength = query.compact.length;
  const budget = typoBudget(queryLength);
  // The shorter side sets the budget, so "pikachu" does not collapse into "pichu".
  const wholeBudget = Math.min(budget, typoBudget(key.compact.length));
  if (wholeBudget > 0) {
    const whole = editDistance(query.compact, key.compact, wholeBudget);
    if (whole <= wholeBudget) return SCORE.fuzzy - whole * 20;
  }
  // While typing, the first letter is assumed right — it keeps short queries from matching half the dex.
  if (
    budget > 0 &&
    key.compact.length > queryLength &&
    key.compact.charCodeAt(0) === query.compact.charCodeAt(0)
  ) {
    const partial = editDistance(query.compact, key.compact.slice(0, queryLength), budget);
    if (partial <= budget) return SCORE.fuzzy - partial * 20 - 10;
  }
  return 0;
}

interface DexQuery {
  id: number;
  /** Typed with leading zeros (`025`): an exact number, not the start of one. */
  padded: boolean;
  /** Typed with `#` / `no.`: certainly a number, never part of a name. */
  explicit: boolean;
}

/** `25`, `#025`, `no. 25` → 25; null when the query is not a dex number. */
function parseDexQuery(raw: string): DexQuery | null {
  // NFKC folds full-width digits and `＃` to their ASCII forms.
  const match = /^(#|no\.?\s*)?\s*(\d{1,5})$/i.exec(raw.normalize('NFKC').trim());
  if (!match?.[2]) return null;
  return {
    id: Number.parseInt(match[2], 10),
    padded: match[2].length > 1 && match[2].startsWith('0'),
    explicit: match[1] !== undefined,
  };
}

function toResult(item: SearchItem, score: number, match: SearchMatchKind): SpeciesSearchResult {
  return {
    species: item.species,
    form: item.form,
    pokemonId: item.pokemonId,
    name: item.name,
    types: item.types,
    match,
    score,
  };
}

/**
 * Ranked offline search across species and their huntable forms.
 *
 * - Text is matched diacritic-, case- and punctuation-insensitively
 *   (`flabebe`, `mr mime`, `farfetchd`, `type null`, `nidoran f`).
 * - A number (`25`, `#025`) finds that National Dex entry first.
 * - Forms are found by their own names in either word order
 *   (`alolan vulpix`, `vulpix alola`). A form whose species matched is listed
 *   right after it; forms found only through their own wording (`a` → every
 *   "Alolan …") come after the species of the same tier.
 * - A typo is forgiven only when nothing matches as typed.
 * - An empty query lists everything that passes the filters, in dex order.
 *
 * Ties are broken by National Dex number, so results are stable.
 */
export function searchSpecies(
  query: string,
  options: SpeciesSearchOptions = {},
): SpeciesSearchResult[] {
  const limit = Math.floor(options.limit ?? DEFAULT_SEARCH_LIMIT);
  if (!(limit > 0)) return [];

  const generation = options.generation ?? null;
  const type = options.type ? options.type.trim().toLowerCase() : null;
  const includeForms = options.includeForms ?? true;
  const passesFilters = (item: SearchItem): boolean =>
    (includeForms || item.form === null) &&
    (generation === null || item.species.gen === generation) &&
    (type === null || item.types.includes(type));

  const normalized = normalizeSearchText(query);
  const dex = parseDexQuery(query);

  if (normalized === '' && !dex) {
    // Nothing typed (or only punctuation): browse mode.
    if (query.trim() !== '') return [];
    const listing: SpeciesSearchResult[] = [];
    for (const item of SEARCH_ITEMS) {
      if (!passesFilters(item)) continue;
      listing.push(toResult(item, 0, 'all'));
      if (listing.length >= limit) break;
    }
    return listing;
  }

  const queryKey = toKey(normalized);
  const dexDigits = dex ? String(dex.id) : null;
  const matchText = normalized !== '' && !dex?.explicit;
  const hits: { item: SearchItem; score: number; order: number }[] = [];
  const misses: { item: SearchItem; order: number }[] = [];
  // Score of each base species, filters aside — tells whether a form hit accompanies its species.
  const speciesScores = new Map<number, number>();
  // Whether the query matched anything at all, filters aside.
  let recognised = false;

  for (let order = 0; order < SEARCH_ITEMS.length; order += 1) {
    const item = SEARCH_ITEMS[order];
    if (!item) continue;

    let score = 0;
    if (dex && dexDigits) {
      if (item.pokemonId === dex.id) score = SCORE.dexExact;
      // "25" also surfaces #250-259 while typing; a zero-padded "#025" is taken literally.
      else if (!dex.padded && item.form === null && String(item.species.id).startsWith(dexDigits)) {
        score = SCORE.dexPrefix;
      }
    }
    if (matchText && score < SCORE.exact) {
      for (const key of item.keys) {
        const keyScore = scoreKey(key, queryKey);
        if (keyScore > score) score = keyScore;
        if (score >= SCORE.exact) break;
      }
    }

    if (score > 0) {
      recognised = true;
      if (item.form === null) speciesScores.set(item.species.id, score);
    }
    if (!passesFilters(item)) continue;
    if (score > 0) hits.push({ item, score, order });
    else misses.push({ item, order });
  }

  // Typo tolerance is a rescue for queries that match nothing. It stays off
  // when real matches exist — even ones the filters removed — because mixing
  // near-misses into (or substituting them for) real results only misleads.
  if (!recognised && !dex) {
    for (const { item, order } of misses) {
      let score = 0;
      for (const key of item.keys) {
        const keyScore = fuzzyScore(key, queryKey);
        if (keyScore > score) score = keyScore;
      }
      if (score > 0) hits.push({ item, score, order });
    }
  }

  // Within a tier: species (each followed by its forms) in dex order, then
  // "orphan" forms whose species did not match as well as they did.
  const isOrphan = (hit: { item: SearchItem; score: number }): number =>
    hit.item.form !== null && (speciesScores.get(hit.item.species.id) ?? 0) < hit.score ? 1 : 0;
  hits.sort((a, b) => b.score - a.score || isOrphan(a) - isOrphan(b) || a.order - b.order);
  return hits.slice(0, limit).map(({ item, score }) => toResult(item, score, matchKindFor(score)));
}
